import * as fs from "node:fs";
export default function (pi: any) {
  let forced = false;
  pi.on("before_agent_start", () => (forced ? { systemPrompt: "OPAQUE_FORCED_POLICY" } : undefined));
  pi.registerCommand("eq-force", { description: "harness: force the system prompt for later runs (on|off)", handler: async (args: string) => { forced = args.trim() === "on"; } });
  pi.registerCommand("eq-wake", {
    description: "harness: an idle custom message that triggers a turn",
    handler: async () => { pi.sendMessage({ customType: "background-completion", content: "BACKGROUND_COMPLETION: inspect current state.", display: true }, { triggerTurn: true }); },
  });
  pi.registerCommand("eq-settings", {
    description: "harness: merge a JSON object into the agent settings file and reload",
    handler: async (args: string, ctx: any) => {
      const space = args.indexOf(" ");
      const file = args.slice(0, space);
      const patch = JSON.parse(args.slice(space + 1));
      const current = JSON.parse(fs.readFileSync(file, "utf8"));
      for (const [key, value] of Object.entries(patch)) current[key] = { ...(current[key] ?? {}), ...(value as object) };
      fs.writeFileSync(file, JSON.stringify(current));
      await ctx.reload();
    },
  });
  pi.registerCommand("eq-tools", { description: "harness: set the active tools (comma list)", handler: async (args: string) => { pi.setActiveTools(args.trim().split(",")); } });
}
